#include "dfre/mission_trail_frame.hpp"
#include <cstring>
#include <iostream>
#include <map>
#include <memory>
#include <sstream>
using namespace dfre;
namespace {
using U=std::uint32_t;using H=std::uint64_t;
std::int32_t si(U n){std::int32_t v;std::memcpy(&v,&n,4);return v;}
void hash(H& h,U kind,U address,U value=0){for(U n:{kind,address,value})for(U i=0;i<4;++i){h^=(n>>(8*i))&255;h*=1099511628211ull;}}
template<class T>H bytes_hash(const std::vector<T>& data){H h=1469598103934665603ull;for(auto n:data)for(unsigned i=0;i<sizeof(T);++i){h^=(U(n)>>(i*8))&255;h*=1099511628211ull;}return h;}
constexpr U camera=0x1200000,base=0x9e3098;
U read_in(std::istream& in){std::uint64_t value;if(!(in>>value))throw MissionTrailError("Short trail fixture");return U(value);}
void pixel(std::istream& in){MissionTrailLine line;for(auto& point:line.vertices)for(auto& value:point)value=si(read_in(in));line.color=read_in(in);line.alpha=std::uint8_t(read_in(in));const U seed=read_in(in);std::vector<U> color(32*24);std::vector<std::uint16_t> depth(color.size());for(U i=0;i<color.size();++i){color[i]=0x12345678u^(seed*65537+i*71);depth[i]=std::uint16_t(seed+i*113);}bool failed=false;std::size_t writes=0;try{writes=mission_trail_draw32(line,{2,3,29,20},32,24,color,depth);}catch(const MissionTrailError&){failed=true;}std::cout<<failed<<' '<<writes<<' '<<bytes_hash(color)<<' '<<bytes_hash(depth)<<'\n';}
void endpoint(std::istream& in){MissionTrailPoint a,b;for(auto& n:a)n=si(read_in(in));for(auto& n:b)n=si(read_in(in));const auto da=si(read_in(in)),db=si(read_in(in));bool failed=false;try{mission_trail_clip_endpoint(a,b,da,db);}catch(const MissionTrailError&){failed=true;}std::cout<<failed;for(auto n:a)std::cout<<' '<<U(n);for(auto n:b)std::cout<<' '<<U(n);std::cout<<'\n';}
void integrated(std::istream& in){U v[9];for(auto& n:v)n=read_in(in);auto cells=std::make_unique<MissionProjectileTrailCells>();MissionTrailFrameClock clock;clock.previous_a158a0=v[1];U tick=v[0],demo=v[2];ModelCameraFrame camera;camera.matrix=model_identity_matrix();camera.projection.focal_length=32;camera.projection.centre={16,12};camera.clip={2,3,29,20};camera.planes.resize(5);camera.planes[0].normal={0x400000,0,0};camera.planes[0].offset=4096;
 const U slots[]={0,2047};for(U j=0;j<2;++j){const U x=v[5+j],y=j?0xffff8000u:0x8000u;cells->records_9e3098[slots[j]]={x,y,0x4000,x+4096,j?0xfffe8000u:0x18000u,0x8000,v[3+j],v[7]+j*0x11223344};}
 std::vector<U> color(32*24);std::vector<std::uint16_t> depth(color.size());for(U i=0;i<color.size();++i){color[i]=0x12345678u^(v[8]*65537+i*71);depth[i]=std::uint16_t(v[8]+i*113);}std::size_t writes=0;bool failed=false;auto b=mission_trail_frame_bindings(*cells,clock,tick,demo,camera,[&](const auto& line){writes+=mission_trail_draw32(line,camera.clip,32,24,color,depth);});try{mission_trail_frame(b);}catch(const MissionTrailError&){failed=true;}std::cout<<failed<<' '<<clock.previous_a158a0<<' '<<cells->records_9e3098[0][6]<<' '<<cells->records_9e3098[2047][6]<<' '<<writes<<' '<<bytes_hash(color)<<' '<<bytes_hash(depth)<<'\n';}
void clip(std::istream& in){std::map<U,U> memory;for(U i=0;i<20;++i)memory[camera+0x1880+i*4]=read_in(in);MissionTrailPoint a,b;for(auto& n:a)n=si(read_in(in));for(auto& n:b)n=si(read_in(in));const U mutation=read_in(in);H h=1469598103934665603ull;unsigned other=0;bool used=false,failed=false,result=false;
 auto read=[&](U at){hash(h,1,at);if(!used&&mutation==1&&at==camera+0x1880){a[0]=si(U(a[0])+65536);used=true;}if(!used&&mutation==2&&at==camera+0x1894){a[1]=si(U(a[1])+131072);used=true;}if(mutation==3&&at==camera+0x1890&&++other==2){b[0]=si(U(b[0])+262144);}if(!used&&mutation==4&&at==camera+0x188c){a[0]=si(U(a[0])+32768);used=true;}if(!used&&mutation==5&&at==camera+0x1880){memory[at]=0x200000;used=true;}return memory[at];};
 try{result=mission_trail_clip(read,camera,a,b);}catch(const MissionTrailError&){failed=true;}std::cout<<failed<<' '<<result;for(auto n:a)std::cout<<' '<<U(n);for(auto n:b)std::cout<<' '<<U(n);std::cout<<' '<<h<<'\n';}
void frame(std::istream& in){U v[9];for(auto& n:v)n=read_in(in);const auto mutation=v[8];std::map<U,U> memory;auto get=[&](U at){return memory[at];};auto put=[&](U at,U value){memory[at]=value;};put(0x6e4724,v[0]);put(0xa158a0,v[1]);put(0x6e4718,v[2]);put(camera+0x54,32);put(camera+0x58,16);put(camera+0x5c,12);put(camera+0x1880,0x400000);put(camera+0x188c,4096);for(U i=0;i<12;++i)put(camera+0x1920+i*4,i==0||i==5||i==10?0x400000:0);
 const U slots[]={0,1,2047};for(U j=0;j<3;++j){const auto at=base+slots[j]*32;put(at,v[6]);put(at+4,0x8000+j*1024);put(at+8,0x4000);put(at+12,v[6]+16384);put(at+16,0x10000+j*2048);put(at+20,0x8000);put(at+24,v[3+j]);put(at+28,v[7]+j*0x11223344);}
 H h=1469598103934665603ull;U transforms=0;std::vector<MissionTrailLine> draws;bool used=false,failed=false;MissionTrailFrameBindings b;
 b.read=[&](U at){hash(h,1,at);if(mutation==4&&at==0x6e4724)put(0xa158a0,get(at)+1);if(!used&&mutation==7&&at==camera+0x54){put(at,48);put(base+28,0xaabbccdd);used=true;}if(mutation==8&&at==base+28){put(base+24,0);put(camera+0x54,96);}return get(at);};
 b.write=[&](U at,U value){hash(h,2,at,value);if(mutation==5&&at==0xa158a0)throw MissionTrailError("Clock test error");if(mutation==6&&at==base+24&&value==0)throw MissionTrailError("Clear test error");put(at,value);};
 b.transform=[&](U matrix,U at){hash(h,3,matrix,at);++transforms;if(mutation==1&&transforms==1){put(base+12,v[6]+32768);put(base+16,0x20000);put(base+24,12345);put(base+28,0x13579bdf);}if(mutation==2&&transforms==2){put(camera+0x54,48);put(0x6e4724,get(0x6e4724)+100);put(0x6e4718,1);}ModelMatrix m;for(U i=0;i<12;++i)m[i]=si(get(matrix+i*4));return model_transform_point(m,{si(get(at)),si(get(at+4)),si(get(at+8))});};
 b.draw=[&](const MissionTrailLine& line){hash(h,4,0xa00,line.color);draws.push_back(line);if(mutation==3&&draws.size()==1){put(base+2047*32+24,30);put(base+2047*32,0x40000);put(0x6e4724,get(0x6e4724)+7);}if(mutation==9)throw MissionTrailError("Draw test error");};if(mutation==10)b.transform={};if(mutation==11)b.draw={};
 try{mission_trail_frame(b,camera);}catch(const MissionTrailError&){failed=true;}std::cout<<failed<<' '<<get(0xa158a0)<<' '<<get(0x6e4724)<<' '<<get(0x6e4718)<<' '<<transforms<<' '<<draws.size()<<' '<<h;for(U slot:slots)for(U i=0;i<8;++i)std::cout<<' '<<get(base+slot*32+i*4);for(const auto& line:draws){for(const auto& point:line.vertices)for(auto n:point)std::cout<<' '<<U(n);std::cout<<' '<<line.color<<' '<<U(line.alpha);}std::cout<<'\n';}
}
int main(){try{std::string text;while(std::getline(std::cin,text)){std::istringstream in(text);char mode;if(!(in>>mode))continue;if(mode=='P')pixel(in);else if(mode=='C')clip(in);else if(mode=='E')endpoint(in);else if(mode=='F')frame(in);else if(mode=='I')integrated(in);else throw MissionTrailError("Unknown trail fixture mode");}}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
